//! The contracts/pot events the chain reader follows, and their decoding.
//!
//! Each event is named by the role of the contract that emits it and its first
//! topic, never by the topic alone: the Launcher and the Treasury both emit a
//! `WoundDown`, and the two Share tokens are one contract code with one
//! `Transfer`. The table of events ([`EVENTS`]) is generated by
//! `scripts/chain-reader-events.mjs` from the contracts build, never typed by
//! hand; the tests below compare it with `testdata/pot-events.json`, which
//! holds the topics forge itself reports.

use std::sync::OnceLock;

use buzz_evm_allowance::abi::keccak256;
use serde_json::{Map, Value};

use super::word::{hex0x, word_to_address, word_to_decimal, word_to_signed_decimal, Word};

/// Which contract emitted a log.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Role {
    /// The one Launcher the reader is configured with.
    Launcher,
    /// A project's backer Shares (ERC-20).
    Shares,
    /// A project's Team Shares (ERC-20, the same code as the backer Shares).
    Team,
    /// A project's Treasury.
    Treasury,
    /// A project's Vester.
    Vester,
    /// A Pair runner (two signers), named by `Launcher.PairMade`.
    Pair,
    /// A project's task queue (`TaskBook`), found from its Treasury's
    /// `TasksReady` log.
    Tasks,
    /// A project's holder pause (`HolderPause`), found from its Treasury's
    /// `PauseReady` log. Only projects launched by a deployment whose pause
    /// switch is on have one.
    Pause,
    /// The deployment's earlier backers' claim contract (`EarlierGrants`),
    /// found from the Launcher's `EarlierBound` log and tied to the one
    /// project that log names.
    Earlier,
    /// A project's Council (five seats, three needed), found from the
    /// Launcher's `CouncilMade` log. Only projects of a deployment whose Council
    /// switch is on have one.
    Council,
    /// The dollar token (the play dollar on a test network). It is in the
    /// table so its events decode, but the reader does not follow it: every
    /// transfer of the dollar on the chain would be read for nothing, and the
    /// dollars a project holds are read from the chain, not counted.
    Dollar,
}

impl Role {
    /// The name stored in `chain_contracts.role` and `chain_logs.role`.
    pub fn as_str(self) -> &'static str {
        match self {
            Role::Launcher => "launcher",
            Role::Shares => "shares",
            Role::Team => "team",
            Role::Treasury => "treasury",
            Role::Vester => "vester",
            Role::Pair => "pair",
            Role::Tasks => "tasks",
            Role::Pause => "pause",
            Role::Earlier => "earlier",
            Role::Council => "council",
            Role::Dollar => "dollar",
        }
    }

    /// The role named by [`Role::as_str`].
    pub fn parse(text: &str) -> Option<Self> {
        Some(match text {
            "launcher" => Role::Launcher,
            "shares" => Role::Shares,
            "team" => Role::Team,
            "treasury" => Role::Treasury,
            "vester" => Role::Vester,
            "pair" => Role::Pair,
            "tasks" => Role::Tasks,
            "pause" => Role::Pause,
            "earlier" => Role::Earlier,
            "council" => Role::Council,
            "dollar" => Role::Dollar,
            _ => return None,
        })
    }
}

/// An ABI parameter type, as far as these events need.
#[derive(Debug)]
pub enum Ty {
    /// `address`.
    Address,
    /// `uintN`, kept with its Solidity name for the signature.
    Uint(&'static str),
    /// `intN` (two's complement), kept with its Solidity name; decoded as a
    /// signed decimal string.
    Int(&'static str),
    /// `bool`.
    Bool,
    /// `bytes32`.
    Bytes32,
    /// `bytes` (dynamic; only `Pair.Proposed.data`).
    Bytes,
    /// A static struct: its fields in order.
    Tuple(&'static [Param]),
    /// A fixed-length array of a static type: the element type and its length.
    Array(&'static Ty, usize),
}

/// One event parameter.
#[derive(Debug)]
pub struct Param {
    /// The parameter's name in the source (the key in the decoded JSON).
    pub name: &'static str,
    /// Its type.
    pub ty: Ty,
    /// Whether it is an indexed topic.
    pub indexed: bool,
}

/// One event the reader follows.
#[derive(Debug)]
pub struct EventDef {
    /// The emitting contract's role.
    pub role: Role,
    /// The event's name in the source.
    pub name: &'static str,
    /// Its parameters in order.
    pub params: &'static [Param],
}

pub(super) const fn p(name: &'static str, ty: Ty) -> Param {
    Param {
        name,
        ty,
        indexed: false,
    }
}

pub(super) const fn ix(name: &'static str, ty: Ty) -> Param {
    Param {
        name,
        ty,
        indexed: true,
    }
}

pub(super) const U256: Ty = Ty::Uint("uint256");
pub(super) const U64: Ty = Ty::Uint("uint64");

#[path = "events_table.rs"]
mod table;
pub use table::EVENTS;

fn type_name(ty: &Ty, out: &mut String) {
    match ty {
        Ty::Address => out.push_str("address"),
        Ty::Uint(name) | Ty::Int(name) => out.push_str(name),
        Ty::Bool => out.push_str("bool"),
        Ty::Bytes32 => out.push_str("bytes32"),
        Ty::Bytes => out.push_str("bytes"),
        Ty::Tuple(fields) => {
            out.push('(');
            for (i, field) in fields.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                type_name(&field.ty, out);
            }
            out.push(')');
        }
        Ty::Array(inner, len) => {
            type_name(inner, out);
            out.push('[');
            out.push_str(&len.to_string());
            out.push(']');
        }
    }
}

impl EventDef {
    /// The canonical signature, e.g. `Asked(uint256,address,uint256,uint256)`.
    pub fn signature(&self) -> String {
        let mut out = String::from(self.name);
        out.push('(');
        for (i, param) in self.params.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            type_name(&param.ty, &mut out);
        }
        out.push(')');
        out
    }

    /// The first topic: keccak256 of the signature.
    pub fn topic(&self) -> Word {
        keccak256(self.signature().as_bytes())
    }
}

fn table() -> &'static [(Role, Word, &'static EventDef)] {
    static TABLE: OnceLock<Vec<(Role, Word, &'static EventDef)>> = OnceLock::new();
    TABLE.get_or_init(|| EVENTS.iter().map(|e| (e.role, e.topic(), e)).collect())
}

/// The event `role` emits under `topic0`, if the reader knows it.
pub fn lookup(role: Role, topic0: &Word) -> Option<&'static EventDef> {
    table()
        .iter()
        .find(|(r, t, _)| *r == role && t == topic0)
        .map(|(_, _, e)| *e)
}

/// The first topic of `role`'s event `name`, if the reader knows it.
pub fn topic_of(role: Role, name: &str) -> Option<Word> {
    table()
        .iter()
        .find(|(r, _, e)| *r == role && e.name == name)
        .map(|(_, t, _)| *t)
}

/// Every first topic the reader follows (for a `topics[0]` filter).
pub fn all_topics() -> Vec<Word> {
    let mut topics: Vec<Word> = table().iter().map(|(_, t, _)| *t).collect();
    topics.sort();
    topics.dedup();
    topics
}

/// Why a log could not be decoded.
#[derive(Debug, PartialEq, Eq)]
pub enum DecodeError {
    /// Fewer or more topics than the event's indexed parameters.
    Topics,
    /// The data is shorter than the parameters, or a `bytes` offset is wrong.
    Data,
}

fn static_words(ty: &Ty) -> usize {
    match ty {
        Ty::Tuple(fields) => fields.iter().map(|f| static_words(&f.ty)).sum(),
        Ty::Array(inner, len) => static_words(inner) * len,
        _ => 1,
    }
}

fn word_at(data: &[u8], index: usize) -> Result<Word, DecodeError> {
    let start = index.checked_mul(32).ok_or(DecodeError::Data)?;
    let slice = data.get(start..start + 32).ok_or(DecodeError::Data)?;
    let mut w = [0u8; 32];
    w.copy_from_slice(slice);
    Ok(w)
}

fn scalar(ty: &Ty, w: &Word) -> Value {
    match ty {
        Ty::Address => Value::String(hex0x(&word_to_address(w))),
        Ty::Uint(_) => Value::String(word_to_decimal(w)),
        Ty::Int(_) => Value::String(word_to_signed_decimal(w)),
        Ty::Bool => Value::Bool(w[31] != 0),
        Ty::Bytes32 => Value::String(hex0x(w)),
        // Indexed dynamic values are hashes; not used by these events.
        Ty::Bytes | Ty::Tuple(_) | Ty::Array(_, _) => Value::String(hex0x(w)),
    }
}

fn decode_static(ty: &Ty, data: &[u8], cursor: &mut usize) -> Result<Value, DecodeError> {
    match ty {
        Ty::Tuple(fields) => {
            let mut obj = Map::new();
            for field in fields.iter() {
                obj.insert(
                    field.name.to_owned(),
                    decode_static(&field.ty, data, cursor)?,
                );
            }
            Ok(Value::Object(obj))
        }
        Ty::Array(inner, len) => {
            let mut items = Vec::with_capacity(*len);
            for _ in 0..*len {
                items.push(decode_static(inner, data, cursor)?);
            }
            Ok(Value::Array(items))
        }
        _ => {
            let w = word_at(data, *cursor)?;
            *cursor += 1;
            Ok(scalar(ty, &w))
        }
    }
}

/// Decode one log's topics and data into a JSON object of its parameters.
/// Integers are decimal strings, addresses and fixed bytes `0x` hex.
pub fn decode(def: &EventDef, topics: &[Word], data: &[u8]) -> Result<Value, DecodeError> {
    let indexed = def.params.iter().filter(|p| p.indexed).count();
    if topics.len() != indexed + 1 {
        return Err(DecodeError::Topics);
    }
    let head_words: usize = def
        .params
        .iter()
        .filter(|p| !p.indexed)
        .map(|p| static_words(&p.ty))
        .sum();
    if data.len() < head_words * 32 {
        return Err(DecodeError::Data);
    }
    let mut out = Map::new();
    let mut topic = 1;
    let mut cursor = 0usize;
    for param in def.params {
        let value = if param.indexed {
            let v = scalar(&param.ty, &topics[topic]);
            topic += 1;
            v
        } else if matches!(param.ty, Ty::Bytes) {
            let offset_word = word_at(data, cursor)?;
            cursor += 1;
            let offset = super::word::word_to_u128(&offset_word)
                .and_then(|v| usize::try_from(v).ok())
                .ok_or(DecodeError::Data)?;
            if offset % 32 != 0 {
                return Err(DecodeError::Data);
            }
            let len_word = word_at(data, offset / 32)?;
            let len = super::word::word_to_u128(&len_word)
                .and_then(|v| usize::try_from(v).ok())
                .ok_or(DecodeError::Data)?;
            let start = offset + 32;
            let bytes = data
                .get(start..start.checked_add(len).ok_or(DecodeError::Data)?)
                .ok_or(DecodeError::Data)?;
            Value::String(hex0x(bytes))
        } else {
            decode_static(&param.ty, data, &mut cursor)?
        };
        out.insert(param.name.to_owned(), value);
    }
    Ok(Value::Object(out))
}

